INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','easy','flashcard','What fasting plasma glucose level confirms diabetes mellitus?','[">=7.0 mmol/L (126 mg/dL) on two separate occasions in asymptomatic patients, or once with classic symptoms (polyuria, polydipsia, weight loss)"]','A','Two abnormal values required without symptoms; one value sufficient when classic symptoms are present. FPG 6.1-6.9 mmol/L = impaired fasting glucose (pre-diabetes).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','easy','flashcard','What 2-hour OGTT glucose value is diagnostic of diabetes mellitus?','[">=11.1 mmol/L (200 mg/dL) on a 75 g oral glucose tolerance test. Values 7.8-11.0 mmol/L = impaired glucose tolerance (pre-diabetes)."]','A','OGTT is the gold standard for diagnosing gestational diabetes and borderline cases. Normal 2-hour glucose: <7.8 mmol/L.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','easy','flashcard','What HbA1c level is diagnostic of diabetes mellitus?','[">=48 mmol/mol (>=6.5%). HbA1c 39-47 mmol/mol (5.7-6.4%) = pre-diabetes. Must use a standardised certified assay."]','A','HbA1c is unreliable in haemolytic anaemia, haemoglobinopathies (sickle cell), and recent blood transfusion -- use fructosamine or CGM instead in these conditions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','flashcard','What are the four WHO/ADA diagnostic criteria for diabetes mellitus?','["1. FPG >=7.0 mmol/L x2 (or x1 with symptoms); 2. 2-hr OGTT >=11.1 mmol/L; 3. HbA1c >=48 mmol/mol (6.5%); 4. Random plasma glucose >=11.1 mmol/L WITH classic symptoms"]','A','Any one criterion on two separate occasions (or once with symptoms) confirms diagnosis. All four are equivalent diagnostic thresholds.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','flashcard','What is the gold-standard insulin regimen for Type 1 diabetes mellitus?','["Basal-bolus regimen: long-acting insulin analogue once daily (e.g. glargine/detemir/degludec) + rapid-acting analogue (lispro/aspart/glulisine) before each meal"]','A','Best mimics physiological insulin secretion. CSII (insulin pump) is an alternative. Pre-mixed insulins offer less flexibility and are not preferred in T1DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','flashcard','State the sick-day rules for a patient with Type 1 DM who is unwell with vomiting and glucose 22 mmol/L.','["NEVER stop insulin -- illness increases counter-regulatory hormones causing insulin resistance. Check ketones every 1-2 hours. Give extra rapid-acting correction doses. If vomiting prevents oral intake or ketones >3 mmol/L, attend hospital for IV fluids and insulin."]','A','The most dangerous sick-day error is withholding insulin because the patient is not eating. This rapidly leads to DKA in Type 1 DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','hard','flashcard','A Type 1 DM patient on basal-bolus insulin has consistently elevated fasting glucoses (12-14 mmol/L) with good post-meal control. What adjustment is needed?','["Increase the basal insulin (e.g. glargine) by 2 units every 3 days until fasting glucose reaches target (4-7 mmol/L). Do NOT adjust the bolus insulin for fasting hyperglycaemia."]','A','Fasting glucose reflects overnight basal insulin adequacy. Post-meal glucose reflects bolus insulin adequacy. This distinction guides which component of the regimen to adjust.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','easy','flashcard','A random plasma glucose of 15.2 mmol/L with classic symptoms of diabetes. Is a second test required?','["No. A single random plasma glucose >=11.1 mmol/L WITH classic symptoms (polyuria, polydipsia, unexplained weight loss) is sufficient to diagnose diabetes mellitus without repeat testing."]','A','Only asymptomatic patients require two abnormal values. Classic symptoms + one abnormal result = diagnosis confirmed. Avoid delaying insulin in symptomatic patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','hard','flashcard','A CSII (pump) user develops glucose 22 mmol/L and ketones 3+ with a 4-day-old infusion set. What is the priority action?','["Give subcutaneous rapid-acting insulin injection (bypassing the pump) immediately AND replace the infusion set. Attend hospital for DKA assessment."]','A','Cannula occlusion/failure is a common cause of DKA in pump users. Never assume the pump is delivering insulin if glucose is rising with ketones -- bypass the pump with SC injection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','flashcard','What is impaired fasting glucose (IFG) and what intervention is recommended?','["FPG 6.1-6.9 mmol/L with normal 2-hour OGTT glucose. Not diagnostic of diabetes but indicates pre-diabetes. Intervention: intensive lifestyle modification (weight loss 5-10%, 150 min/week moderate exercise, dietary change) reduces progression to diabetes by ~58% (DPP trial)."]','A','IFG carries ~5-10% annual risk of progression to T2DM. Annual HbA1c or FPG monitoring is recommended.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','easy','flashcard','According to Ghana STG 2017, what is the first-line treatment for Type 2 DM?','["Metformin -- start at 500 mg BD with meals, titrate to 1-2 g/day. Reduces hepatic glucose production (AMPK activation) and improves insulin sensitivity. Low hypoglycaemia risk. HbA1c target: <53 mmol/mol (<7%)."]','A','Ghana STG 2017 endorses metformin as first-line consistent with ADA/NICE/WHO guidelines. It also has evidence for reducing all-cause mortality in overweight T2DM patients (UKPDS).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','easy','flashcard','What is the standard HbA1c target for most adults with Type 2 DM?','["<53 mmol/mol (<7.0%). Tighter targets (<48 mmol/mol / <6.5%) may be appropriate in young patients early in disease. Relaxed targets (<=69-75 mmol/mol / <=8.5-9.0%) are used for frail elderly, those with hypoglycaemia unawareness, or limited life expectancy."]','A','Individualised targets: consider age, comorbidities, hypoglycaemia risk, and life expectancy. The ACCORD trial showed intensive control increased mortality in high-risk patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','flashcard','When is metformin contraindicated?','["eGFR <30 mL/min/1.73m2 (risk of lactic acidosis from accumulation). Also withhold 48 hours before IV contrast procedures if eGFR <60. Reduce dose if eGFR 30-44 mL/min."]','A','MHRA guidance: eGFR 45-59 -- continue with monitoring; eGFR 30-44 -- reduce dose and review; eGFR <30 -- STOP metformin. Lactic acidosis with metformin is rare but potentially fatal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','flashcard','Which drug classes have PROVEN cardiovascular mortality benefit in T2DM with established atherosclerotic CVD?','["SGLT-2 inhibitors (e.g. empagliflozin -- EMPA-REG reduced CV death 38%) and GLP-1 receptor agonists (e.g. liraglutide -- LEADER reduced CV death 22%; semaglutide -- SUSTAIN-6 reduced MACE). These are guideline-preferred second agents after metformin in patients with established ASCVD."]','A','Both classes also provide renoprotection. Sulfonylureas have no proven CV mortality benefit. DPP-4 inhibitors are CV-neutral (saxagliptin may increase HF risk). Pioglitazone is CV-neutral.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','hard','flashcard','A 48-year-old obese patient with T2DM (BMI 36) on metformin wants to lose weight. Which add-on therapy is best?','["GLP-1 receptor agonist (e.g. semaglutide or liraglutide) -- provides significant weight loss (5-15% body weight) via appetite suppression and delayed gastric emptying, alongside HbA1c reduction. Semaglutide also has proven CV benefit."]','A','Sulfonylureas and thiazolidinediones cause weight gain. DPP-4 inhibitors are weight-neutral. GLP-1 RAs are the preferred add-on for obese patients wanting weight loss with glucose control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','flashcard','What is the mechanism of action of metformin?','["Primary: activates hepatic AMPK (AMP-activated protein kinase), suppressing gluconeogenic enzymes (PEPCK, G6Pase) -- reducing fasting hepatic glucose output. Secondary: improves peripheral insulin sensitivity; modest reduction in intestinal glucose absorption."]','A','Because metformin does NOT stimulate insulin secretion, hypoglycaemia is rare as monotherapy. It is weight-neutral to weight-reducing. It also positively modifies gut microbiome and bile acid metabolism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','easy','flashcard','What is the blood pressure target for a patient with Type 2 DM and diabetic nephropathy?','["<130/80 mmHg. First-choice antihypertensives: ACE inhibitors (e.g. lisinopril) or ARBs (e.g. losartan) -- reduce intraglomerular pressure, decrease proteinuria by 30-40%, and slow GFR decline independently of BP lowering."]','A','Combination ACEi + ARB is NOT recommended (increases risk of hyperkalaemia and AKI -- ONTARGET trial). Monitor UACR and eGFR annually in all diabetic patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','hard','flashcard','What HbA1c target is appropriate for a frail 74-year-old with T2DM, multiple comorbidities, and hypoglycaemia unawareness?','["Relaxed target: HbA1c <=69-75 mmol/mol (<=8.5-9.0%). Benefits of tight control (microvascular protection) take 5-10 years and do not outweigh the risks of hypoglycaemia (falls, fractures, cardiovascular events) in frail elderly patients."]','A','The ACCORD trial showed that intensive glucose lowering increased all-cause mortality in high-risk T2DM patients. Frail elderly patients need individualised targets and deprescribing of agents with high hypoglycaemia risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','flashcard','What is the most important side effect of glibenclamide (sulfonylurea) to counsel patients about?','["Hypoglycaemia -- especially prolonged episodes in elderly patients, those with renal impairment (active metabolite accumulation), or those who skip meals. Glibenclamide has the HIGHEST risk of all sulfonylureas due to its long half-life."]','A','Gliclazide MR (modified release) is preferred over glibenclamide in elderly/renal impairment as it has a shorter duration and no active metabolites. All patients starting sulfonylureas must receive hypoglycaemia education.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','easy','flashcard','Name the step-up treatment algorithm for Type 2 DM according to Ghana STG 2017.','["Step 1: Lifestyle modification + metformin 500 mg BD. Step 2: Add glibenclamide (sulfonylurea) if HbA1c target not met after 3 months. Step 3: Add insulin (bedtime basal insulin) or intensify insulin regimen."]','A','Ghana STG recommends this stepwise approach. In patients with established CVD, international guidelines now recommend SGLT-2 inhibitors or GLP-1 RAs at Step 2, but these may not be available in all resource-limited settings.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','easy','flashcard','State the THREE diagnostic criteria for DKA.','["1. Hyperglycaemia: blood glucose >11 mmol/L (euglycaemic DKA can occur with SGLT-2 inhibitors); 2. Metabolic acidosis: pH <7.3 and/or bicarbonate <15 mmol/L; 3. Ketonaemia >=3 mmol/L OR ketonuria 2+ on dipstick."]','A','DKA results from absolute/relative insulin deficiency with counter-regulatory hormone excess (cortisol, glucagon, adrenaline) promoting lipolysis and ketogenesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','easy','flashcard','What is the FIRST-LINE IV fluid in DKA?','["0.9% NaCl (normal saline) -- 1 L over 1 hour initially (faster if shocked). 5% dextrose is added only when blood glucose falls below 14 mmol/L."]','A','Add dextrose at glucose <14 mmol/L to allow continued insulin infusion without causing hypoglycaemia. Insulin must continue until ketoacidosis resolves, not just until glucose normalises.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','flashcard','What is the standard fixed-rate IV insulin infusion rate in DKA?','["0.1 units/kg/hr of human soluble insulin (e.g. Actrapid). Weight-based. Start AFTER beginning IV fluid resuscitation. Continue long-acting subcutaneous insulin (e.g. glargine) alongside FRIII."]','A','The FRIII is not titrated to glucose levels -- it is continued until DKA resolution criteria are met. Stopping insulin too early (when glucose normalises) causes rebound ketosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','flashcard','State the THREE DKA resolution criteria that must ALL be met before stopping insulin infusion.','["1. Blood ketones <0.6 mmol/L; 2. Venous pH >7.3; 3. Bicarbonate >18 mmol/L. ALL three must be met. Glucose normalisation alone is NOT sufficient to stop insulin infusion."]','A','After meeting resolution criteria and patient can eat, give the first subcutaneous insulin dose 30-60 minutes BEFORE stopping the IV insulin infusion to prevent a gap in coverage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','hard','flashcard','In DKA, what is the danger of starting insulin before correcting potassium if K+ <3.5 mmol/L?','["Insulin drives potassium into cells (activation of Na/K-ATPase). If serum K+ is already low (<3.5 mmol/L), insulin will cause FATAL HYPOKALAEMIA and cardiac arrhythmias. Correct K+ to >=3.5 mmol/L with IV KCl BEFORE starting insulin."]','A','K+ protocol in DKA: K+ <3.5 -- hold insulin, give IV KCl; K+ 3.5-5.5 -- start insulin + add 40 mmol KCl per litre of fluid; K+ >5.5 -- start insulin without KCl. Monitor K+ every 1-2 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','easy','flashcard','Name FOUR common precipitants of DKA.','["1. Missed/insufficient insulin (most common); 2. Infection (UTI, pneumonia, cellulitis); 3. New-onset Type 1 DM (25-30% of DKA cases); 4. Other: MI, pancreatitis, surgery, SGLT-2 inhibitors (euglycaemic DKA), corticosteroids."]','A','Always search for a precipitant in DKA -- treating the precipitant prevents recurrence. Screen for infection (FBC, CRP, cultures, CXR, urine MC&S) in all DKA patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','flashcard','How is DKA severity classified?','["By venous pH: Mild: pH 7.25-7.30 (bicarbonate 15-18 mmol/L); Moderate: pH 7.00-7.24 (bicarbonate 10-14 mmol/L); Severe: pH <7.00 (bicarbonate <10 mmol/L). Severity determines monitoring intensity and need for HDU/ICU."]','A','Severe DKA requires HDU or ICU admission, more frequent blood gas monitoring, and senior clinical involvement. GCS <12 is an additional indication for HDU/ICU.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','hard','flashcard','When is IV sodium bicarbonate considered in DKA according to JBDS guidelines?','["ONLY if venous pH <6.9 after initial resuscitation. Given as 100 mmol over 1 hour with additional potassium. ONLY after senior/specialist discussion. Routine use is NOT recommended."]','A','Routine bicarbonate in DKA risks: paradoxical CNS acidosis, worsening hypokalaemia, shift of O2-haemoglobin dissociation curve (reduced O2 delivery), and rebound alkalosis. Fluid and insulin remain the cornerstone of treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','flashcard','What is cerebral oedema in DKA and how is it managed?','["A rare but life-threatening complication of DKA, more common in young patients and children. Caused by overly rapid fluid/osmolality correction. Features: headache, deteriorating GCS, pupil changes, bradycardia. Treatment: mannitol 0.5-1 g/kg IV or 3% hypertonic saline."]','A','Prevention: follow JBDS fluid protocols, avoid excessive free water, do not correct osmolality too rapidly. Cerebral oedema in DKA carries ~20-40% mortality. Urgent CT head and critical care involvement required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','easy','flashcard','When is it safe to transition from IV to subcutaneous insulin in DKA?','["When ALL resolution criteria are met (ketones <0.6, pH >7.3, bicarbonate >18 mmol/L) AND the patient is alert and able to eat and drink. Give the first SC dose 30-60 minutes BEFORE stopping the IV infusion."]','A','Give the correct subcutaneous regimen -- for new-onset T1DM this requires a structured basal-bolus regimen with diabetes specialist input. Never stop IV insulin without SC insulin cover in place.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','easy','flashcard','State the diagnostic criteria for HHS.','["Blood glucose >30 mmol/L + effective osmolality >320 mOsm/kg (= 2x[Na] + [glucose]) + absent/minimal ketoacidosis (pH >7.3, bicarb >15, ketones <3 mmol/L) + profound dehydration (fluid deficit 8-10 L)."]','A','HHS predominantly affects elderly Type 2 DM patients. Mortality is higher than DKA (~15-20% vs <2%). Common precipitants: infection, MI, stroke, new medications (steroids, diuretics).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','flashcard','How does HHS differ from DKA (3 key differences)?','["1. Glucose: HHS >30 (often >50) vs DKA >11 mmol/L; 2. Ketosis: HHS minimal/absent vs DKA significant (>=3 mmol/L); 3. Patient type: HHS elderly T2DM vs DKA predominantly T1DM. Both can cause altered consciousness."]','A','Residual insulin in T2DM prevents lipolysis and ketogenesis in HHS. The extreme hyperglycaemia and hyperosmolality in HHS cause profound osmotic diuresis and dehydration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','easy','flashcard','What is the first-line treatment for mild/moderate hypoglycaemia in a CONSCIOUS patient able to swallow?','["Rule of 15: 15-20 g fast-acting oral carbohydrate (4-5 glucose tablets, 200 mL orange juice, 150 mL Lucozade). Recheck glucose at 15 minutes. Repeat if still <4 mmol/L. Follow with a longer-acting starchy snack."]','A','Never give oral glucose to an unconscious patient (aspiration risk). IV dextrose or IM glucagon is required for unconscious patients or those unable to swallow.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','flashcard','What is the treatment for severe hypoglycaemia in an unconscious patient with IV access?','["IV 10% dextrose 150-200 mL over 15 minutes (or IV 20% dextrose 75-100 mL). Preferred over IV 50% dextrose which is irritant to veins and risks tissue necrosis if extravasated. Recheck glucose every 15 minutes."]','A','50% dextrose (25 g/50 mL) is highly hypertonic -- avoid extravasation. Once conscious and able to swallow, give starchy snack. Consider glucose infusion for long-acting agent-induced hypoglycaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','hard','flashcard','What is the treatment for severe hypoglycaemia in an unconscious patient WITHOUT IV access?','["Glucagon 1 mg intramuscular (or subcutaneous) injection. Stimulates hepatic glycogenolysis, raising glucose in 10-15 minutes. May be less effective in glycogen-depleted patients (starvation, alcohol excess, adrenal insufficiency)."]','A','All patients on insulin or sulfonylureas should have a glucagon kit at home (with trained family member). Once IV access is gained, give IV dextrose. Address the cause to prevent recurrence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','flashcard','What is the formula for EFFECTIVE osmolality (used in HHS)?','["Effective osmolality = 2 x [Na] + [glucose] (both in mmol/L). Urea is EXCLUDED because it freely crosses cell membranes and does not contribute to effective osmotic pressure or water shifts between compartments."]','A','Normal effective osmolality: 275-295 mOsm/kg. In HHS: >320 mOsm/kg. Total osmolality (2x(Na+K) + glucose + urea) includes urea but is NOT the correct formula for assessing tonicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','hard','flashcard','What is hypoglycaemia unawareness and how is it managed?','["Loss of autonomic warning symptoms (tremor, sweating, palpitations) at glucose <3.5 mmol/L due to repeated hypoglycaemia blunting counter-regulatory responses (glucagon, adrenaline). Patients develop neuroglycopenic symptoms (confusion, seizure) without warning."]','A','Management: relax glucose targets, structured education (DAFNE programme), continuous glucose monitoring (CGM) with low glucose alarms, review medications. Hypoglycaemia unawareness increases fatal hypoglycaemia risk 6-fold.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','easy','flashcard','Which conditions cause FALSELY LOW HbA1c?','["Haemolytic anaemia, haemoglobinopathies (HbS/HbC/HbE -- sickle cell disease), recent blood transfusion (new unglycated RBCs), iron deficiency anaemia. In these patients, use fructosamine or continuous glucose monitoring (CGM) instead."]','A','HbA1c reflects average glucose over the red cell lifespan (~120 days). Conditions shortening RBC survival falsely lower HbA1c. Splenectomy (prolonged RBC survival) causes falsely HIGH HbA1c.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','flashcard','What is the initial fluid management for HHS?','["IV 0.9% NaCl: 1 L over 1 hour initially, then titrated based on response. Total fluid deficit 8-10 L; replace over 24-48 hours. Target: osmolality falls no faster than 3-8 mOsm/kg/hr; glucose falls no faster than 5 mmol/L/hr."]','A','Rapid osmolality correction in HHS risks cerebral oedema. Low-dose insulin (0.05 units/kg/hr) is only started if glucose fails to fall with fluids alone. DVT prophylaxis with LMWH is essential (high thrombosis risk in HHS).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','hard','flashcard','An elderly patient with HHS has glucose 58 mmol/L, osmolality 368 mOsm/kg, and is confused. What is the most critical initial action?','["Aggressive IV 0.9% NaCl rehydration -- 1-2 L over the first 1-2 hours for hypotension, then continued at 500 mL/hr. Fluid replacement is the MOST CRITICAL intervention in HHS -- it alone will lower glucose and osmolality significantly."]','A','Low-dose insulin (0.05 units/kg/hr) is only added after initial fluid resuscitation and if glucose is not falling. Starting insulin before adequate fluid replacement risks vascular collapse (osmotic shifts). Identify and treat the precipitant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','easy','flashcard','What is the first-line treatment for primary hypothyroidism and what is the monitoring target?','["Levothyroxine (L-T4) oral therapy. Starting dose: 1.6 mcg/kg/day in young adults; 12.5-25 mcg/day in elderly or cardiac patients. Monitoring: TSH within normal range (0.4-4.0 mU/L) checked 6-8 weeks after dose change."]','A','Taken 30-60 minutes before food (or at bedtime). TSH is the most sensitive monitoring parameter in primary hypothyroidism. Annual TSH monitoring once stable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','easy','flashcard','Why must levothyroxine be started at a LOW dose in elderly patients with ischaemic heart disease?','["Thyroid hormone increases heart rate, myocardial contractility, and oxygen demand. Full replacement doses in elderly/cardiac patients risk precipitating angina, myocardial infarction, or cardiac arrhythmias. Start at 12.5-25 mcg/day and titrate slowly."]','A','Increase dose by 25 mcg every 6-8 weeks. Monitor for cardiac symptoms at each dose increase. ECG and cardiology review if AF or angina develops on initiation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','flashcard','Name FOUR substances that REDUCE levothyroxine absorption.','["Calcium carbonate (reduces absorption by ~40%), ferrous sulphate (iron), proton pump inhibitors/antacids, coffee (taken within 60 minutes), cholestyramine, soy products. Separate levothyroxine from these by at least 4 hours."]','A','A patient with persistently elevated TSH despite dose increases should be asked about timing of levothyroxine relative to food, coffee, and medications. This is a common cause of apparent levothyroxine resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','flashcard','Define subclinical hypothyroidism. When should it be treated?','["TSH elevated (4.5-10 mU/L) + NORMAL free T4 + no or minimal symptoms. TREAT if: TSH >10 mU/L (high risk of progression); pregnant (any TSH elevation -- treat to protect fetus); significant symptoms; anti-TPO antibody positive."]','A','In asymptomatic elderly patients with TSH 4.5-10 mU/L: watchful waiting with 6-monthly monitoring is acceptable (TSH rises physiologically with age). Anti-TPO positivity predicts ~4% annual progression risk to overt hypothyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','hard','flashcard','A pregnant woman (12 weeks) has TSH 6.8 mU/L and positive anti-TPO antibodies. What is the correct management and TSH target?','["Start levothyroxine immediately to protect fetal neurodevelopment. TSH targets in pregnancy: first trimester <2.5 mU/L; second and third trimester <3.0 mU/L. The levothyroxine dose typically needs to increase by 25-50% during pregnancy."]','A','The fetus is entirely dependent on maternal T4 for brain development until the fetal thyroid becomes active (~10-12 weeks). Even subclinical hypothyroidism in pregnancy is associated with reduced fetal IQ and obstetric complications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','hard','flashcard','What is myxoedema coma and how is it treated?','["Life-threatening emergency of severe decompensated hypothyroidism: reduced consciousness, hypothermia, bradycardia, hyponatraemia. Mortality 40-60%. Treatment: (1) IV levothyroxine 200-500 mcg stat + optional IV liothyronine; (2) IV hydrocortisone 100 mg BEFORE thyroid hormone (prevent adrenal crisis); (3) Passive rewarming; (4) ICU admission."]','A','Hydrocortisone MUST be given before thyroid hormone because thyroid hormone accelerates cortisol metabolism -- in adrenal-insufficient patients this can precipitate Addisonian crisis. Treat precipitant (infection, MI, cold exposure).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','easy','flashcard','Which antibody is the hallmark of Hashimoto thyroiditis?','["Anti-thyroid peroxidase (anti-TPO) antibodies -- present in >90% of Hashimoto thyroiditis. Anti-thyroglobulin antibodies are also elevated but less sensitive and specific."]','A','Distinguishing from Graves disease: TRAb/TSI (TSH receptor stimulating antibodies) are the hallmark of Graves disease and cause hyperthyroidism. Anti-TPO antibodies are elevated in both conditions but are not specific for Graves.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','flashcard','A patient on levothyroxine has suppressed TSH (0.05 mU/L) with palpitations. What is the management and the clinical concern?','["Reduce the levothyroxine dose and recheck TSH in 6-8 weeks. Suppressed TSH indicates over-replacement (iatrogenic thyrotoxicosis). Risks: atrial fibrillation (3x increased risk), osteoporosis (reduced bone mineral density, especially in postmenopausal women)."]','A','Target TSH: 0.4-4.0 mU/L for most patients. In thyroid cancer patients after total thyroidectomy, a suppressed TSH may be intentional (TSH suppression to reduce cancer recurrence risk) -- do not reduce dose without oncology input.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','hard','flashcard','Which drug INCREASES levothyroxine requirements by inducing CYP450 enzymes?','["Rifampicin (most potent), phenytoin, carbamazepine, phenobarbitone. These induce hepatic CYP450 enzymes, accelerating T4 metabolism and reducing levothyroxine efficacy."]','A','When these drugs are started in a patient on stable levothyroxine, increase the dose by ~50% and monitor TSH every 4-6 weeks. Also note: amiodarone inhibits T4-to-T3 conversion and blocks thyroid function (causing both hypo- and hyperthyroidism).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','flashcard','What condition causes hypothyroidism with LOW TSH (rather than elevated TSH)?','["Secondary (central) hypothyroidism from ACTH/TSH-deficient hypopituitarism. The pituitary fails to secrete adequate TSH, leading to thyroid atrophy and low T4/T3 -- but TSH is low/normal (not elevated). Diagnose with free T4 measurement."]','A','In panhypopituitarism, ALWAYS replace hydrocortisone BEFORE levothyroxine (thyroid hormone accelerates cortisol metabolism and can precipitate adrenal crisis if cortisol is not replaced first).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','easy','flashcard','What is the most common cause of hyperthyroidism and what antibodies confirm the diagnosis?','["Graves disease (60-80% of hyperthyroidism). Confirmed by TRAb (TSH receptor antibodies) or TSI (thyroid stimulating immunoglobulins) -- present in >95% of Graves disease. Autoimmune TSH receptor stimulation drives unregulated T3/T4 production."]','A','Unique features of Graves: ophthalmopathy (exophthalmos, lid retraction, ophthalmoplegia), pretibial myxoedema, thyroid acropachy. None of these occur in toxic nodular goitre or thyroiditis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','easy','flashcard','Which antithyroid drug is preferred in the first trimester of pregnancy and why?','["Propylthiouracil (PTU) is preferred in the first trimester. Carbimazole/methimazole is associated with embryopathy (aplasia cutis, choanal atresia, oesophageal atresia) when used in early pregnancy. Switch to carbimazole from the second trimester (PTU has rare but serious hepatotoxicity)."]','A','Radioiodine is absolutely contraindicated in pregnancy and breastfeeding (destroys the fetal thyroid). Surgery (thyroidectomy) is reserved for cases uncontrolled by medications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','flashcard','State the Burch-Wartofsky Point Scale domains for diagnosing thyroid storm.','["Five domains: (1) Temperature (thermoregulatory); (2) Heart rate and cardiac features (AF, heart failure); (3) CNS dysfunction (agitation, delirium, psychosis, coma); (4) GI/hepatic dysfunction (nausea, vomiting, jaundice); (5) Precipitating event. Score >=45 = thyroid storm; 25-44 = impending storm."]','A','Thyroid storm is precipitated by: surgery, infection, iodine load (contrast), trauma, MI, radioiodine, cessation of antithyroid drugs. It carries 10-30% mortality without treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','flashcard','State the correct order of treatment in thyroid storm.','["1. PTU 500-1000 mg loading (or carbimazole 60-80 mg) -- blocks synthesis FIRST; 2. Lugol iodine >=1 hour LATER -- blocks release (Wolff-Chaikoff); 3. Propranolol -- controls tachycardia, blocks T4-to-T3 conversion; 4. IV hydrocortisone 100 mg q8h -- reduces T4-to-T3 conversion, prevents adrenal insufficiency; 5. Treat precipitant."]','A','CRITICAL: Lugol iodine MUST be given at least 1 hour AFTER antithyroid drug. If given first, iodine can transiently increase hormone synthesis (Jod-Basedow effect), worsening the crisis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','easy','flashcard','Which drug class provides RAPID symptom control in hyperthyroidism while antithyroid drugs take effect?','["Beta-adrenergic blockers (propranolol 40 mg TDS or atenolol). Rapidly control tachycardia, palpitations, tremor, anxiety, and heat intolerance. High-dose propranolol (>160 mg/day) also inhibits peripheral T4-to-T3 conversion."]','A','Antithyroid drugs (carbimazole, PTU) take 4-8 weeks to achieve euthyroidism by blocking new hormone synthesis. Beta-blockers provide symptomatic relief during this period.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','hard','flashcard','What is the most common long-term outcome after radioiodine (I-131) treatment for Graves disease?','["Hypothyroidism -- occurring in 50-80% within 1 year and up to 90% by 10 years. All patients must be counselled about likely lifelong levothyroxine requirement and monitored with TSH every 6-12 months."]','A','Radioiodine contraindications: pregnancy, breastfeeding, severe active Graves ophthalmopathy (can worsen -- prophylactic oral prednisolone given if mild-moderate eye disease). Not associated with increased cancer risk in adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','hard','flashcard','What is the MOST DANGEROUS adverse effect of carbimazole/PTU, and how should patients be counselled?','["Agranulocytosis (neutrophils <0.5x10^9/L) -- occurs in ~0.3% of patients, typically within the first 3 months. Presentation: fever, sore throat, mouth ulcers. Action: STOP carbimazole IMMEDIATELY and obtain urgent FBC."]','A','Counsel ALL patients starting carbimazole or PTU: "If you develop fever, sore throat, or mouth ulcers, stop the medication immediately and seek urgent blood tests." Do not wait for test results before stopping the drug.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','flashcard','What are the TWO mechanisms of action of propylthiouracil (PTU)?','["1. Inhibits thyroid peroxidase (TPO) -- blocks iodination of tyrosine in thyroglobulin (preventing T3/T4 synthesis); 2. Inhibits 5-prime deiodinase (type 1) -- blocks peripheral conversion of T4 to the more potent T3. This dual action makes PTU superior to carbimazole in thyroid storm."]','A','Carbimazole (converted to methimazole) only has action 1 (inhibits TPO) -- it does NOT block T4-to-T3 conversion. Both drugs take 4-8 weeks to achieve euthyroidism. PTU is preferred in: first trimester pregnancy and thyroid storm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','flashcard','What are the THREE treatment options for Graves hyperthyroidism and when is each preferred?','["1. Antithyroid drugs (carbimazole/PTU): for young patients, small goitre, mild disease; 12-18 months then assess for remission. 2. Radioiodine (I-131): for relapse, older patients, no ophthalmopathy; results in hypothyroidism. 3. Total thyroidectomy: for large goitre, severe ophthalmopathy, pregnancy after first trimester, patient preference."]','A','The goal of antithyroid drug treatment is remission (~50% rate after 12-18 months). Predictors of remission: small goitre, mild disease, declining TRAb titres. High TRAb titres predict relapse.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','easy','flashcard','What additional benefit do high doses of propranolol provide in thyroid storm beyond heart rate control?','["High-dose propranolol (>160 mg/day) inhibits peripheral deiodination of T4 to T3 (5-prime deiodinase type 1 inhibition), complementing PTUs same effect. This rapidly reduces circulating T3 levels -- the most active and dangerous thyroid hormone in thyroid storm."]','A','In thyroid storm, the dual anti-T3 effect of propranolol + PTU is a major reason PTU is preferred over carbimazole. IV propranolol 0.5-1 mg IV slowly can be used if oral is not possible -- monitor closely for hypotension and bradycardia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','easy','flashcard','What is the standard SCREENING test for Cushing syndrome?','["Overnight 1 mg dexamethasone suppression test (DST): 1 mg dexamethasone at 23:00; cortisol measured at 08:00-09:00. NORMAL: cortisol <50 nmol/L. POSITIVE (fail to suppress): cortisol >=50 nmol/L. Positive screen requires confirmatory testing."]','A','False positives: alcohol excess, depression, obesity, physical stress, enzyme-inducing drugs (rifampicin, phenytoin -- reduce dexamethasone levels). Also use 24-hr urinary free cortisol or late-night salivary cortisol as alternative screens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','flashcard','What is the CONFIRMATORY test for Cushing syndrome after a positive overnight DST?','["Low-dose dexamethasone suppression test (LDDST): 0.5 mg dexamethasone every 6 hours for 48 hours (total 2 mg). Cortisol measured at 48 hours. Normal: <50 nmol/L. FAILS to suppress in Cushing syndrome. Confirms genuine cortisol excess vs pseudo-Cushing states."]','A','Alternative confirmatory tests: 24-hour urinary free cortisol x2 (>3x upper limit of normal), late-night salivary cortisol x2 (should be low at midnight). Each test has different sensitivity/specificity -- use two different tests for confirmation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','flashcard','What does the HIGH-DOSE DST (8 mg) determine?','["Distinguishes pituitary-source ACTH (Cushing disease) from ectopic ACTH: In Cushing disease, cortisol SUPPRESSES >50% from baseline (some pituitary glucocorticoid feedback preserved). In ectopic ACTH (small cell lung cancer, carcinoid), cortisol does NOT suppress."]','A','Sensitivity ~80%. IPSS (inferior petrosal sinus sampling) is the gold standard for pituitary vs ectopic differentiation. High-dose DST has largely been replaced by IPSS in many centres.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','easy','flashcard','Name the MOST SPECIFIC clinical features of Cushing syndrome (distinguishing from simple obesity).','["Wide purple striae (>1 cm), proximal myopathy (difficulty rising from chair, climbing stairs), easy bruising, thin atrophic skin, facial plethora. Also: moon face, buffalo hump, supraclavicular fat pads, menstrual irregularities, hypokalaemia, osteoporosis."]','A','Simple obesity features non-specific overlap (hypertension, diabetes, weight gain) but does NOT cause: wide purple striae, proximal myopathy, or easy bruising. Proximal myopathy is the MOST discriminating feature.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','hard','flashcard','A patient with ACTH-dependent Cushing syndrome has a normal pituitary MRI. What is the gold standard next investigation?','["Inferior petrosal sinus sampling (IPSS) with CRH stimulation. Simultaneously measures ACTH in both inferior petrosal sinuses (draining the pituitary) and peripheral blood before and after CRH. Central:peripheral ACTH ratio >2 (pre-CRH) or >3 (post-CRH) = pituitary source. Below threshold = ectopic ACTH."]','A','Up to 40% of pituitary corticotroph microadenomas are undetectable on MRI. IPSS can confirm pituitary source even with a normal MRI and provides lateralisation (which side of pituitary the tumour is on) for surgical planning.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','hard','flashcard','What is the first-line treatment for Cushing disease (pituitary ACTH-secreting adenoma)?','["Transsphenoidal surgery (TSS) -- selective adenomectomy by an experienced pituitary neurosurgeon. Remission rates: microadenomas 70-90%; macroadenomas 40-60%. Success confirmed by post-operative cortisol <50 nmol/L within 24-48 hours."]','A','If TSS fails: repeat TSS, pituitary radiotherapy (stereotactic radiosurgery), bilateral adrenalectomy (risk of Nelson syndrome), or medical therapy (metyrapone, ketoconazole, pasireotide).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','hard','flashcard','What is Nelson syndrome and when does it occur?','["Rapid enlargement of a residual ACTH-secreting pituitary tumour after bilateral adrenalectomy for Cushing disease. Removal of the adrenal glands eliminates cortisol feedback, driving aggressive tumour growth with very high ACTH and MSH (causing hyperpigmentation) and mass effects (visual field defects, headache)."]','A','Occurs in 8-43% after bilateral adrenalectomy. Prevention: pituitary radiotherapy before adrenalectomy. Treatment: transsphenoidal surgery, pituitary radiotherapy, temozolomide. Mandatory pituitary MRI surveillance after bilateral adrenalectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','flashcard','What is the biochemical hallmark of ACTH-INDEPENDENT Cushing syndrome?','["Suppressed ACTH (<10 pg/mL) with elevated cortisol. The adrenal tumour (adenoma/carcinoma) autonomously secretes cortisol, suppressing the hypothalamo-pituitary axis via negative feedback (low ACTH). ACTH-dependent causes (pituitary/ectopic) have inappropriately normal or elevated ACTH."]','A','ACTH measurement is the critical first step after confirming Cushing syndrome. It determines whether the source is ACTH-dependent or ACTH-independent, which guides subsequent localisation investigations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','hard','flashcard','A patient with ACTH-independent Cushing syndrome has a unilateral adrenal adenoma. What is the treatment and what perioperative care is needed?','["Laparoscopic unilateral adrenalectomy of the affected side. Perioperative hydrocortisone cover is ESSENTIAL: the contralateral adrenal is suppressed by chronic hypercortisolaemia and cannot respond to surgical stress. IV hydrocortisone 100 mg at induction, then 50 mg q6-8h post-op, stepping down as tolerated."]','A','HPA axis recovery after adrenalectomy takes months to years. Patients need hydrocortisone replacement until the Short Synacthen Test (SST) confirms normal cortisol response. Carry a steroid emergency card during this period.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','flashcard','Name THREE medical agents used in Cushing syndrome and their mechanism.','["1. Metyrapone (11-beta-hydroxylase inhibitor -- reduces cortisol synthesis); 2. Ketoconazole (inhibits multiple steroidogenic enzymes -- reduces cortisol; risk of hepatotoxicity); 3. Pasireotide (somatostatin analogue -- reduces ACTH from pituitary corticotroph adenomas in Cushing disease); 4. Osilodrostat (potent 11-beta-hydroxylase inhibitor); 5. Mifepristone (glucocorticoid receptor antagonist)."]','A','Medical therapy is used as: bridge to surgery, treatment of inoperable tumours, or adjunct after incomplete surgery. Metyrapone is most commonly used in the UK. All agents require careful monitoring for adrenal insufficiency (over-treatment).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','easy','flashcard','State the immediate management of Addisonian crisis.','["IV hydrocortisone 100 mg STAT (IM if IV access delayed). Then: 50-100 mg q6-8h IV or 200 mg/24h continuous infusion. IV 0.9% NaCl: 1 L over 30-60 min for hypotension. Treat hypoglycaemia with dextrose. Do NOT await cortisol result before treating."]','A','Fludrocortisone is NOT needed acutely -- high-dose hydrocortisone has sufficient mineralocorticoid activity. Once stable and tolerating oral intake, convert to oral hydrocortisone + fludrocortisone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','easy','flashcard','What is the classic biochemical triad of PRIMARY adrenal insufficiency (Addison disease)?','["Hyponatraemia + hyperkalaemia + hypoglycaemia. Also: low cortisol + elevated ACTH (loss of negative feedback) + elevated MSH (hyperpigmentation -- skin creases, buccal mucosa, gingiva, nipples, scars)."]','A','In SECONDARY adrenal insufficiency (pituitary ACTH deficiency): cortisol is low, ACTH is low, aldosterone is INTACT (no electrolyte disturbance), no hyperpigmentation. This distinction is critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','medium','flashcard','What is the gold standard diagnostic test for adrenal insufficiency?','["Short Synacthen Test (SST): 250 mcg ACTH analogue (tetracosactide) IV or IM. Cortisol measured at 0, 30, 60 minutes. Normal: peak cortisol >550 nmol/L. Failure to reach this peak confirms adrenal insufficiency. Simultaneous ACTH determines if primary (elevated) or secondary (low/normal)."]','A','Early morning basal cortisol <100 nmol/L is almost diagnostic; >550 nmol/L effectively excludes insufficiency. The SST can appear normal acutely in secondary insufficiency (adrenal atrophy takes 2-4 weeks).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','medium','flashcard','State the perioperative steroid management for a patient with Addison disease having major surgery.','["Major surgery: IV hydrocortisone 100 mg at induction of anaesthesia, then 50 mg IV q6-8h for 24-48 hours. Step down to oral hydrocortisone when eating, reducing gradually over 3-5 days to maintenance dose. Inform anaesthetist and ward team."]','A','NEVER withhold steroids perioperatively in Addison disease. Surgical stress increases cortisol requirements dramatically (normally 10-20 mg/day; major surgery demands 200-400 mg/day equivalent). Failure to cover causes Addisonian crisis with 25% mortality if unrecognised.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','flashcard','State the MAINTENANCE replacement doses for Addison disease.','["Hydrocortisone 15-25 mg/day in divided doses (mimicking diurnal rhythm): 10 mg on waking, 5 mg at noon, 5 mg at 15:00-16:00 (NO late evening dose -- disrupts sleep). Fludrocortisone 50-300 mcg (mean ~100 mcg) once daily for mineralocorticoid replacement."]','A','Adequacy monitoring: electrolytes (normatraemia, normokalaemia), blood pressure lying/standing (no postural hypotension), and RENIN levels (should be in upper normal range -- low renin suggests over-replacement with fludrocortisone).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','easy','flashcard','State the sick-day rules for Addison disease during illness.','["DOUBLE or TRIPLE oral hydrocortisone during any fever, illness, or significant stress. If vomiting prevents oral absorption: attend hospital IMMEDIATELY for IM hydrocortisone 100 mg. All patients must carry: steroid emergency card, IM hydrocortisone kit, and medical alert bracelet."]','A','NEVER reduce steroids during illness. Failure to increase steroids rapidly leads to Addisonian crisis (hypotension, shock, death). Family members should be trained to give IM hydrocortisone if patient becomes incapacitated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','flashcard','What is the most common cause of primary adrenal insufficiency in developed countries vs developing countries?','["Developed countries: autoimmune adrenalitis (~80%) -- antibodies against 21-hydroxylase; often in APS-2 (Addison + T1DM + Hashimoto). Developing countries: tuberculosis -- bilateral adrenal destruction (CT shows calcified adrenals). Other causes: metastases, haemorrhage (Waterhouse-Friderichsen), fungal infections."]','A','APS-2 (Schmidt syndrome): Addison + T1DM + Hashimoto thyroiditis -- the most common autoimmune polyendocrine syndrome. APS-1 (APECED): Addison + hypoparathyroidism + mucocutaneous candidiasis -- associated with AIRE gene mutation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','medium','flashcard','How does secondary adrenal insufficiency differ from Addison disease in terms of biochemistry and treatment?','["Secondary AI: ACTH low/normal, aldosterone INTACT (no fludrocortisone needed), no hyperpigmentation, normal electrolytes. Primary AI (Addison): ACTH elevated, aldosterone deficient (fludrocortisone required), hyperpigmentation, hyponatraemia and hyperkalaemia."]','A','In secondary AI (hypopituitarism), hydrocortisone is prescribed but fludrocortisone is NOT required (the renin-angiotensin-aldosterone system is intact). The SST can be normal acutely in secondary AI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','flashcard','Why is dexamethasone preferred over hydrocortisone when the diagnosis of Addisonian crisis is uncertain?','["Dexamethasone does NOT cross-react with cortisol in standard cortisol immunoassays. This allows a Short Synacthen Test to be performed (for diagnosis) while the patient is simultaneously being treated with dexamethasone 4 mg IV. Hydrocortisone would interfere with cortisol measurement."]','A','Once the SST is completed, switch to hydrocortisone (which has mineralocorticoid activity and is the appropriate physiological replacement). Dexamethasone has NO mineralocorticoid activity, so it alone is not adequate for ongoing maintenance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','flashcard','A patient on long-term prednisolone 10 mg/day becomes hypotensive post-major surgery. How is steroid-induced adrenal crisis prevented?','["By giving perioperative steroid cover: IV hydrocortisone 25-100 mg at induction (depending on surgical severity), continued q6-8h for 24-48h post-op. All patients on long-term steroids (>5 mg prednisolone-equivalent for >4 weeks) must be identified pre-operatively and given steroid cover."]','A','Long-term exogenous steroids suppress the HPA axis, causing secondary adrenal insufficiency. The suppressed adrenal cannot mount a cortisol response to surgical stress. Steroid card must be carried and anaesthetic team informed of steroid dependency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','easy','flashcard','What is the screening test for primary hyperaldosteronism and what result is positive?','["Aldosterone-to-renin ratio (ARR). In primary hyperaldosteronism: autonomous aldosterone secretion (elevated) + suppressed renin (by volume expansion) = markedly elevated ARR. A positive ARR requires confirmatory testing."]','A','Stop interfering medications 2-4 weeks before: spironolactone, eplerenone, amiloride, diuretics. Beta-blockers and ACE inhibitors can be continued but affect interpretation. Ensure adequate K+ repletion before testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','flashcard','What is the classic biochemical triad of primary hyperaldosteronism?','["Hypertension + hypokalaemia + suppressed renin with elevated aldosterone. Also: metabolic alkalosis (H+ loss in exchange for Na+). NOTE: hypokalaemia is present in only ~50% -- many patients present with hypertension alone or resistant hypertension."]','A','Primary hyperaldosteronism accounts for 5-10% of all hypertension and is the most common cause of secondary hypertension. Screen all patients with: resistant hypertension (>3 agents), hypertension + hypokalaemia, or young hypertension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','flashcard','Name TWO confirmatory tests for primary hyperaldosteronism after a positive ARR.','["1. IV saline suppression test: 2 L 0.9% NaCl over 4 hours -- aldosterone fails to suppress to <140 pmol/L. 2. Fludrocortisone suppression test: fludrocortisone 0.1 mg q6h x 4 days -- aldosterone fails to suppress to <170 pmol/L. 3. Also: oral salt loading test; captopril challenge test."]','A','Confirm autonomous aldosterone secretion BEFORE CT adrenals. CT is performed after biochemical confirmation to localise the source (adenoma vs bilateral hyperplasia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','hard','flashcard','Why is adrenal vein sampling (AVS) essential before adrenalectomy for primary hyperaldosteronism?','["CT has ~50% false-localisation rate -- apparent unilateral adenomas may be bilateral hyperplasia (requiring medical, not surgical, treatment). AVS confirms unilateral excess (lateralisation ratio >4:1) before irreversible surgery. Without AVS, ~25% of patients would undergo unnecessary adrenalectomy."]','A','Bilateral hyperplasia on AVS (no lateralisation) = treat medically with spironolactone. Unilateral excess on AVS = laparoscopic adrenalectomy is curative. Even when CT shows a clear unilateral adenoma, AVS is recommended in most centres.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','easy','flashcard','What is the first-line medical treatment for primary hyperaldosteronism (non-surgical cases or bilateral hyperplasia)?','["Spironolactone (mineralocorticoid receptor antagonist) starting at 25-50 mg/day, titrating to 100-400 mg/day. Blocks aldosterone effects: reduces Na+ retention, K+ wasting, hypertension, and metabolic alkalosis."]','A','Side effects: gynaecomastia, mastodynia, menstrual irregularities, hyperkalaemia. Eplerenone is a more selective alternative with fewer sex hormone side effects. Monitor K+ and renal function at 4-6 weeks after starting.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','flashcard','What is the most common subtype of primary hyperaldosteronism and how does it affect management?','["Bilateral idiopathic adrenal hyperplasia (BAH) = most common (~60-65%). Management: medical with spironolactone/eplerenone (surgery does NOT cure hypertension in bilateral disease). Unilateral adenoma (~30-35%) = laparoscopic adrenalectomy (potentially curative)."]','A','AVS distinguishes bilateral hyperplasia from unilateral adenoma more accurately than CT. This distinction is critical because surgery on bilateral hyperplasia does not resolve hypertension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','hard','flashcard','After laparoscopic adrenalectomy for a unilateral aldosterone-producing adenoma, which electrolyte complication must be monitored?','["Hyperkalaemia -- the contralateral zona glomerulosa is chronically suppressed by excess aldosterone from the adenoma. After removal, aldosterone drops precipitously but the contralateral gland takes weeks to months to recover. This transient hypoaldosteronism causes K+ retention (hyperkalaemia) and salt wasting."]','A','Monitor K+ and Na+ closely post-operatively. Temporary fludrocortisone supplementation may be needed. Stop spironolactone pre-operatively. Advise liberal salt intake post-op. Full recovery of the renin-angiotensin-aldosterone axis may take up to 6 months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','flashcard','How does PRIMARY hyperaldosteronism differ biochemically from SECONDARY hyperaldosteronism?','["Primary: autonomous aldosterone + SUPPRESSED renin + elevated ARR (adenoma or bilateral hyperplasia). Secondary: high aldosterone DRIVEN by high renin (appropriate response to reduced renal perfusion: renovascular hypertension, diuretics, heart failure, cirrhosis) -- BOTH aldosterone AND renin elevated, ARR is normal or low."]','A','The ARR is the key distinguishing test. Secondary hyperaldosteronism should be treated by addressing the underlying cause (e.g. renal artery stenting for renovascular hypertension, diuretic dose reduction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','hard','flashcard','Which rare familial subtype of primary hyperaldosteronism responds to dexamethasone and why?','["Familial Hyperaldosteronism Type I (FH-I / glucocorticoid-remediable aldosteronism / GRA). Caused by CYP11B1/CYP11B2 chimeric gene -- aldosterone synthase is under ACTH control. Dexamethasone suppresses ACTH, thereby suppressing aldosterone -- correcting hypertension and hypokalaemia."]','A','Suspect FH-I in patients <40 years with primary hyperaldosteronism and family history of early-onset hypertension or haemorrhagic stroke. Diagnose by genetic testing (PCR-based assay for chimeric gene).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','easy','flashcard','Name two differences between the action of spironolactone and eplerenone in primary hyperaldosteronism.','["Both are mineralocorticoid receptor (MR) antagonists. Differences: (1) Eplerenone is more SELECTIVE for MR (fewer sex hormone side effects -- no gynaecomastia, menstrual irregularities); (2) Eplerenone is less potent per mg and requires higher doses. Spironolactone is cheaper and more widely available."]','A','Spironolactone also blocks androgen and progesterone receptors (causing gynaecomastia and erectile dysfunction in men; menstrual irregularities in women). Eplerenone avoids these off-target effects and is better tolerated in men.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','easy','flashcard','What is the screening test for acromegaly and which is the confirmatory test?','["Screening: serum IGF-1 (elevated for age and sex). Confirmatory: OGTT with GH measurement -- 75 g oral glucose suppresses GH to <1 mcg/L in normal individuals; in acromegaly, GH fails to suppress (remains elevated or paradoxically rises)."]','A','Random GH is unreliable (pulsatile secretion). IGF-1 reflects integrated 24-hour GH secretion and is the best screening test. A normal IGF-1 effectively excludes acromegaly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','flashcard','What investigation is performed after biochemical confirmation of acromegaly?','["Pituitary MRI with gadolinium contrast -- identifies and characterises the GH-secreting somatotroph adenoma. 95% of acromegaly is caused by a pituitary adenoma. MRI assesses tumour size (macro vs micro), cavernous sinus invasion, and optic chiasm proximity."]','A','Most acromegaly adenomas are macroadenomas (>1 cm) due to delayed diagnosis. Cavernous sinus invasion predicts lower surgical cure rates. Ectopic GH secretion (pancreatic tumours, lung carcinoid) is very rare (<1%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','easy','flashcard','What is the first-line treatment for acromegaly caused by a pituitary GH-secreting adenoma?','["Transsphenoidal surgery (TSS) -- selective adenomectomy. Remission rates: microadenomas 70-90%; macroadenomas 40-60%. Biochemical remission: IGF-1 normalises + GH suppresses to <1 mcg/L on OGTT."]','A','If TSS fails: somatostatin analogues (octreotide LAR, lanreotide autogel) as primary medical therapy. Pegvisomant (GH receptor antagonist) if IGF-1 remains elevated on somatostatin analogues. Radiotherapy is third-line.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','hard','flashcard','What is the most common cause of premature death in untreated acromegaly?','["Cardiovascular disease (~60% of excess mortality): biventricular hypertrophy, diastolic dysfunction, hypertension (~30-40%), arrhythmias, accelerated atherosclerosis. Acromegaly doubles mortality. Effective treatment (normalising IGF-1) significantly reduces cardiovascular mortality."]','A','Other risks: sleep apnoea (soft tissue hypertrophy), colorectal polyps/carcinoma (increased surveillance), arthropathy, carpal tunnel syndrome, diabetes mellitus (glucose intolerance from GH excess).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','flashcard','Name the characteristic clinical features of acromegaly.','["Coarsening facial features, frontal bossing, prognathism (jaw protrusion), macroglossia, interdental spacing; enlarged hands/feet (increasing ring/shoe size); hyperhidrosis (excessive sweating); carpal tunnel syndrome; sleep apnoea; arthralgia; hypertension; glucose intolerance/diabetes; visual field defects if chiasmal compression."]','A','Pre-epiphyseal closure: excess GH causes GIGANTISM (excessive linear growth). Post-epiphyseal closure (adults): excess GH causes ACROMEGALY (soft tissue and bone thickening -- epiphyses are closed so no increased height).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','hard','flashcard','What is pituitary apoplexy and how is it managed?','["Haemorrhage or infarction into a pituitary adenoma causing sudden severe headache (thunderclap), visual field defects (bitemporal hemianopia), diplopia/ophthalmoplegia, and acute hypopituitarism. Management: (1) IV hydrocortisone 100 mg stat (acute cortisol deficiency is life-threatening); (2) Urgent neurosurgical trans-sphenoidal decompression if vision is threatened; (3) ICU; (4) MRI pituitary."]','A','Precipitants of pituitary apoplexy: anticoagulation, dynamic pituitary tests (CRH, TRH), dopamine agonists, trauma. Even if no surgical emergency, most patients need hormone replacement (steroids, thyroid hormone) due to acute hypopituitarism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','flashcard','What visual field defect occurs with a superiorly expanding pituitary macroadenoma and why?','["Bitemporal hemianopia (loss of both temporal/outer visual fields). Caused by compression of the OPTIC CHIASM, where nasal fibres (carrying temporal visual field information from both eyes) decussate. Superior expansion of the pituitary adenoma compresses these crossing fibres."]','A','Requires formal visual field testing (Humphrey automated perimetry). Urgent treatment (surgery or medical shrinkage with somatostatin analogues) can restore vision if compression is not chronic/irreversible.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','easy','flashcard','In panhypopituitarism, which hormone must be replaced FIRST and why?','["ACTH deficiency (causing cortisol deficiency) must be replaced FIRST with hydrocortisone. Then levothyroxine (T4). REASON: thyroid hormone accelerates cortisol metabolism -- starting T4 without cortisol replacement in a cortisol-deficient patient can precipitate Addisonian crisis."]','A','Complete pituitary hormone replacement order: (1) Hydrocortisone; (2) Levothyroxine; (3) Sex hormones (testosterone/oestrogen); (4) GH replacement in appropriate adults; (5) DDAVP if diabetes insipidus present.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','hard','flashcard','How do somatostatin analogues work in acromegaly and what is the expected biochemical response?','["Octreotide LAR/lanreotide autogel bind somatostatin receptors (SSTR2 and SSTR5) on somatotroph tumour cells, suppressing GH secretion and reducing tumour volume. Expected response: IGF-1 normalisation and GH suppression in ~50-70% of patients. Also reduces tumour volume by 20-50%."]','A','Given as monthly injections: octreotide LAR 10-40 mg IM; lanreotide autogel 60-120 mg SC. If IGF-1 remains elevated: add or substitute pegvisomant (GH receptor antagonist). Side effects: gallstones, diarrhoea, abdominal discomfort, impaired glucose tolerance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','flashcard','What is the difference between gigantism and acromegaly?','["Gigantism: GH excess occurs BEFORE epiphyseal plate closure (in childhood/adolescence) -- causes excessive linear height growth. Acromegaly: GH excess occurs AFTER epiphyseal plate closure (in adults) -- causes soft tissue and periosteal bone thickening (coarse features, enlarged hands/feet) without increased height."]','A','Both are almost always caused by a GH-secreting pituitary somatotroph adenoma. Gigantism patients are tall at presentation (may reach 2 m+). The two conditions have the same complications (cardiovascular, metabolic, visual) and same treatment approach.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','easy','flashcard','What is the most common cause of hypercalcaemia in outpatient (community) vs inpatient settings?','["OUTPATIENT: Primary hyperparathyroidism (~55%) -- usually solitary parathyroid adenoma. INPATIENT/HOSPITALISED: Malignancy (~65%) -- PTHrP secretion (squamous cell carcinoma, renal, breast) or osteolytic bone metastases (multiple myeloma, breast)."]','A','Distinguishing feature: measure PTH. ELEVATED PTH = primary hyperparathyroidism or FHH. SUPPRESSED PTH = malignancy (measure PTHrP), vitamin D toxicity, granulomatous disease, thyrotoxicosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','flashcard','How does the PTH level help diagnose the CAUSE of hypercalcaemia?','["ELEVATED PTH + high Ca2+ = primary hyperparathyroidism (parathyroid adenoma/hyperplasia) or familial hypocalciuric hypercalcaemia (FHH -- PTH inappropriately normal or mildly elevated). SUPPRESSED PTH + high Ca2+ = malignancy (measure PTHrP), vitamin D toxicity, granulomatous disease (sarcoidosis -- measure 1,25-dihydroxyvitamin D)."]','A','FHH (familial hypocalciuric hypercalcaemia) is distinguished from primary hyperparathyroidism by 24-hr urine calcium/creatinine clearance ratio <0.01 (low urine calcium despite hypercalcaemia) and family history.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','easy','flashcard','What ECG change is seen in hypercalcaemia and what is seen in hypocalcaemia?','["Hypercalcaemia: SHORT QT interval (calcium accelerates ventricular repolarisation). Hypocalcaemia: LONG QT interval (risk of torsades de pointes and ventricular fibrillation). Mnemonic: \"Calcium is Short\" -- Ca2+ = short QT; low Ca2+ = long QT."]','A','Severe hypercalcaemia may also cause bradycardia, PR prolongation, and cardiac arrest. Monitor ECG in Ca2+ >3.0 mmol/L. Hypokalaemia also prolongs QT -- check K+ in all hypocalcaemic patients (concurrent hypokalaemia additive effect on QT).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','flashcard','State the management of severe symptomatic hypercalcaemia (corrected Ca2+ >3.0 mmol/L).','["1. FIRST: IV 0.9% NaCl rehydration 2-4 L/day (hypercalcaemia causes nephrogenic DI and dehydration -- fluid alone lowers Ca2+ by 0.25-0.75 mmol/L); 2. THEN: IV zoledronic acid 4 mg over 15 min (or pamidronate 60-90 mg) after rehydration; 3. Calcitonin 4-8 IU/kg for rapid short-term effect; 4. Treat underlying cause."]','A','Bisphosphonate peak effect: 48-72 hours. Calcitonin effect is rapid but short-lived (tachyphylaxis in 48-72h). For malignancy-related hypercalcaemia: denosumab is an alternative (RANK-L inhibitor). Furosemide is NOT routinely used (only after adequate rehydration to promote calciuresis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','easy','flashcard','State the mnemonic for the clinical features of hypercalcaemia.','["Bones, Stones, Groans, and Psychic Moans: Bones -- bone pain, fractures, subperiosteal resorption; Stones -- renal calculi (calcium oxalate/phosphate), nephrocalcinosis, polyuria/polydipsia; Groans -- nausea, vomiting, constipation, anorexia, peptic ulcers; Psychic Moans -- depression, cognitive impairment, psychosis, coma."]','A','Mild hypercalcaemia (<3.0 mmol/L) may be asymptomatic. Moderate (3.0-3.5 mmol/L): symptoms of Bones/Stones/Groans. Severe (>3.5 mmol/L): CNS features (confusion, coma), cardiac arrhythmias, emergency treatment required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','flashcard','A patient has hypocalcaemia with ELEVATED PTH. What is the most likely cause and how does it differ from hypoparathyroidism?','["Vitamin D deficiency (secondary hyperparathyroidism) -- low vitamin D impairs Ca2+ absorption -- hypocalcaemia -- compensatory PTH elevation. This is SECONDARY hyperparathyroidism. In HYPOPARATHYROIDISM: PTH is LOW/ABSENT (parathyroid gland destruction/absence) causing hypocalcaemia without compensatory PTH rise."]','A','Other causes of hypocalcaemia + elevated PTH: CKD (low 1,25-dihydroxyvitamin D), pseudohypoparathyroidism (PTH resistance), malabsorption. Treatment: vitamin D deficiency -- cholecalciferol. Hypoparathyroidism -- calcium carbonate + calcitriol (active vitamin D).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','hard','flashcard','A patient develops hypocalcaemia 24 hours after total thyroidectomy. Corrected Ca2+ 1.70 mmol/L with perioral tingling and positive Trousseau sign. What is the cause and treatment?','["Cause: inadvertent removal or devascularisation of parathyroid glands during thyroidectomy -- hypoparathyroidism. May be transient (<6 months) or permanent (>6 months). Treatment: ACUTE -- IV calcium gluconate 10 mL of 10% solution over 10 minutes; CHRONIC -- oral calcium carbonate + calcitriol (active vitamin D)."]','A','Transient hypoparathyroidism occurs in ~20-30% after total thyroidectomy; permanent in ~1-2%. All patients should have calcium checked 6-12 hours post-op. Prophylactic oral calcium + calcitriol is given routinely in many centres after total thyroidectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','easy','flashcard','What are Chvostek and Trousseau signs and what do they indicate?','["CHVOSTEK: tapping over the facial nerve (anterior to tragus) causes ipsilateral facial muscle twitching. TROUSSEAU: BP cuff inflated above systolic for 3 minutes causes carpal spasm (\"obstetrician hand\" -- wrist flexion, MCP flexion, IP extension, thumb adduction). Both indicate LATENT TETANY from hypocalcaemia."]','A','Both signs indicate neuromuscular hyperexcitability from hypocalcaemia. Trousseau is more specific than Chvostek. Manifest tetany (spontaneous carpal spasm) and laryngospasm indicate severe hypocalcaemia requiring IV calcium.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','hard','flashcard','What is the formula for corrected calcium and why is it needed?','["Corrected Ca2+ = measured Ca2+ + 0.02 x (40 - albumin [g/L]). Needed because albumin is the main calcium-binding protein -- hypoalbuminaemia lowers TOTAL calcium without affecting IONISED (physiologically active) calcium. Example: measured Ca2+ 2.0, albumin 20 -- corrected = 2.0 + 0.4 = 2.4 mmol/L (normal)."]','A','Direct ionised calcium measurement (blood gas analyser) is the gold standard and does not require correction. Especially important in acid-base disorders where protein binding is altered. In acidosis: more ionised calcium (H+ competes with Ca2+ for albumin binding).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','flashcard','How does PTHrP cause hypercalcaemia in malignancy (humoral hypercalcaemia of malignancy)?','["Tumours (squamous cell carcinoma, renal, breast, bladder) secrete PTHrP, which binds the PTH/PTHrP receptor (PTH1R) with equal affinity to PTH, causing: (1) Bone resorption via RANK-L (osteoclast activation); (2) Increased renal calcium reabsorption; (3) Reduced phosphate reabsorption. PTH is SUPPRESSED by hypercalcaemia."]','A','PTHrP accounts for ~80% of malignancy-related hypercalcaemia. NOT detected by standard PTH assays -- requires specific PTHrP immunoassay. Other mechanisms of malignancy-related hypercalcaemia: osteolytic metastases (direct bone destruction -- multiple myeloma, breast), excess calcitriol (lymphoma), ectopic PTH (very rare).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
